// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;

    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address r, uint256 amount) public {
        vm.assume(r != address(c));
        vm.assume(r != address(this));
        amount = bound(amount, 100, 1e18);

        // fund the contract so the first bonus payout succeeds
        vm.deal(address(c), amount);

        // claim the (first) bonus: pays 100 wei to r and zeroes the reward
        c.getFirstWithdrawalBonus(r);

        uint256 balanceBefore = address(c).balance;

        // second withdrawal: reward already zeroed, sends 0 wei, no balance change
        c.withdrawReward(r);

        assertTrue(address(c).balance == balanceBefore);
    }
}
